import React, {useState, useEffect, useRef} from 'react';
import {Text, View, ScrollView, Pressable, TextInput, Switch, AppState, StatusBar, Share, StyleSheet} from 'react-native';
import * as Haptics from 'expo-haptics';
import {useKeepAwake} from 'expo-keep-awake';
import {useAudioPlayer, setAudioModeAsync} from 'expo-audio';
const {clampBpm, nextBeat} = require('./core.cjs');
const {SyncClient, SyncedClock} = require('./sync-client.cjs');
const INITIAL = {bpm:120, beats:4, playing:false, startAt:0, revision:0};
const RELAY = process.env.EXPO_PUBLIC_RELAY_URL || require('./relay-config.json').url;

export default function App() {
  useKeepAwake();
  const [state,setState] = useState(INITIAL);
  const [beat,setBeat] = useState(-1);
  const [haptic,setHaptic] = useState(true);
  const [sound,setSound] = useState(false);
  const [advance,setAdvance] = useState(0);
  const [room,setRoom] = useState(null);
  const [members,setMembers] = useState([]);
  const [code,setCode] = useState('');
  const [name,setName] = useState('밴드 멤버');
  const [address,setAddress] = useState(RELAY);
  const [status,setStatus] = useState('혼자 연습 · 준비 완료');
  const [phase,setPhase] = useState('solo');
  const [busy,setBusy] = useState(false);
  const [active,setActive] = useState(true);
  const sync = useRef(null);
  const soloClock = useRef(new SyncedClock());
  const taps = useRef([]);
  const current = useRef({state,haptic,sound});
  current.current = {state,haptic,sound};
  const click = useAudioPlayer(require('./assets/click.wav'));
  const accent = useAudioPlayer(require('./assets/accent.wav'));
  const canEdit = !room || room.isHost;
  const online = phase === 'ready';

  useEffect(() => {
    setAudioModeAsync({playsInSilentMode:true}).catch(()=>setStatus('소리 초기화 실패'));
    const subscription = AppState.addEventListener('change', value => {
      setActive(value === 'active');
      if(value === 'active') sync.current?.resume();
      else {sync.current?.suspend();setPhase(sync.current?'paused':'solo');}
    });
    return () => {subscription.remove();sync.current?.close();};
  }, []);

  async function connect(create) {
    if(busy || state.playing) return;
    if(!address.trim()) {setStatus('온라인 중계 서버 배포가 아직 필요합니다.');return;}
    setBusy(true);
    const client = new SyncClient({
      url:address.trim(),
      onSnapshot: data => {
        if(sync.current !== client) return;
        setMembers(data.members);
        if(client.session) setRoom(client.session);
        setState(old => old.revision === data.state.revision ? old : data.state);
      },
      onStatus: data => {
        if(sync.current !== client) return;
        setPhase(data.phase);
        setStatus(data.phase === 'ready' ? `온라인 · 왕복 ${Math.round(data.rtt)}ms` : ({warming:'서버 준비 중… 무료 서버는 첫 연결에 약 1분 걸릴 수 있어요.',connecting:'연결 중…',syncing:'휴대폰 시계 맞추는 중…',reconnecting:'연결 복구 중 · 출력 정지'}[data.phase] || data.phase));
      },
      onClosed: () => {
        if(sync.current !== client) return;
        sync.current=null;setRoom(null);setMembers([]);setState(INITIAL);setPhase('solo');setStatus('방이 종료되었습니다. 새 방에 참여하세요.');
      }
    });
    sync.current?.close();sync.current=client;
    setState(INITIAL);
    try {
      const session=await client.connect({create,code,name});
      if(sync.current===client)setRoom(session);
    } catch(e) {
      if(sync.current===client){sync.current=null;setRoom(null);setMembers([]);setState(INITIAL);setPhase('solo');setStatus(e.message);}
    } finally {setBusy(false);}
  }

  async function change(patch) {
    if(!canEdit||busy)return;
    const next={...state,...patch};
    if(room) {
      setBusy(true);
      try {
        const data=await sync.current.update(next);
        setState(old=>old.revision>data.state.revision?old:data.state);
      }catch(e){setStatus(e.message);}finally{setBusy(false);}
    } else setState({...next,startAt:soloClock.current.now()+150,revision:state.revision+1});
  }

  async function leave() {
    if(busy)return;setBusy(true);
    const old=sync.current;sync.current=null;
    setRoom(null);setMembers([]);setState(INITIAL);setPhase('solo');
    try {await old?.leave();setStatus('혼자 연습 · 준비 완료');}
    catch {setStatus('연결을 종료했습니다.');}
    finally {setBusy(false);}
  }

  useEffect(() => {
    if(!state.playing||!active||(room&&!online)){setBeat(-1);return;}
    let cancelled=false,timer;
    const clock=room?sync.current.clock:soloClock.current;
    let index=nextBeat(clock.now(),state,advance).index;
    function tick() {
      if(cancelled)return;
      if(room&&!sync.current?.isHealthy()){setBeat(-1);timer=setTimeout(tick,100);return;}
      const now=clock.now(), period=60000/state.bpm;
      const target=state.startAt+index*period-advance, delay=target-now;
      if(delay>1){timer=setTimeout(tick,Math.max(1,delay-1));return;}
      if(-delay>Math.min(80,period/2)){index=nextBeat(now,state,advance).index;timer=setTimeout(tick,1);return;}
      const b=index%state.beats;setBeat(b);
      if(current.current.haptic)Haptics.impactAsync(b===0?Haptics.ImpactFeedbackStyle.Heavy:Haptics.ImpactFeedbackStyle.Light).catch(()=>setStatus('기기 진동을 사용할 수 없습니다.'));
      if(current.current.sound){const player=b===0?accent:click;player.seekTo(0).then(()=>{if(!cancelled)player.play();}).catch(()=>setStatus('소리를 재생하지 못했습니다.'));}
      index++;
      timer=setTimeout(tick,Math.max(1,state.startAt+index*period-advance-clock.now()-2));
    }
    tick();return()=>{cancelled=true;clearTimeout(timer);};
  },[state,advance,active,room,online]);

  function tap() {
    const now=performance.now();
    taps.current=taps.current.filter(t=>now-t<3000).concat(now).slice(-5);
    if(taps.current.length>1)change({bpm:clampBpm(60000*(taps.current.length-1)/(now-taps.current[0]))});
  }
  const button=(label,onPress,selected=false,disabled=false)=>(
    <Pressable accessibilityRole="button" accessibilityState={{disabled,selected}} disabled={disabled} onPress={onPress} style={[s.button,selected&&s.selected,disabled&&{opacity:.35}]}>
      <Text style={[s.buttonText,selected&&{color:'#091311'}]}>{label}</Text>
    </Pressable>
  );
  const locked=!canEdit||busy||state.playing||(room&&!online);
  return <View style={s.screen}>
    <StatusBar barStyle="light-content"/>
    <ScrollView contentContainerStyle={s.content} keyboardShouldPersistTaps="handled">
      <View style={s.row}><Text style={s.logo}>◉ PULSE BAND</Text><Text style={s.tag}>PLAY TOGETHER</Text></View>
      <Text style={s.title}>같은 박자, 같은 순간.</Text>
      <Text style={s.muted}>어디서 연결하든, 우리 밴드의 리듬은 하나로.</Text>
      <View style={s.card}>
        <View style={s.row}><Text style={s.green}>{room?`● ROOM ${room.code}`:'● SOLO SESSION'}</Text><Text style={s.muted}>{room?(room.isHost?'방장 휴대폰':'멤버'):'혼자 연습'}</Text></View>
        <Text style={s.bpm}>{state.bpm}</Text><Text style={s.unit}>BEATS PER MINUTE</Text>
        <View style={s.center}>{button('−',()=>change({bpm:clampBpm(state.bpm-1)}),false,locked)}{button('TAP TEMPO',tap,false,locked)}{button('+',()=>change({bpm:clampBpm(state.bpm+1)}),false,locked)}</View>
        <View style={s.center}>{Array.from({length:state.beats},(_,i)=><View key={i} style={[s.dot,beat===i&&s.lit]}><Text style={{color:beat===i?'#10221c':'#74877f'}}>{i+1}</Text></View>)}</View>
        <View style={s.center}>{[3,4,6,7].map(n=><React.Fragment key={n}>{button(`${n}/4`,()=>change({beats:n}),state.beats===n,locked)}</React.Fragment>)}</View>
        {button(state.playing?'■  정지':'▶  함께 시작',()=>change({playing:!state.playing}),true,!canEdit||busy||(room&&!online))}
        <Text style={s.note}>{!canEdit?'방장 휴대폰이 템포와 재생을 제어합니다.':state.playing?'템포와 박자는 정지 후 변경할 수 있어요.':'연결 상태에 맞춰 잠시 준비한 뒤 함께 시작합니다.'}</Text>
      </View>
      <View style={s.card}>
        <Text style={s.section}>나만의 비트 출력</Text>
        <View style={s.row}><View><Text style={s.label}>박자 진동</Text><Text style={s.muted}>첫 박은 강하게, 나머지는 가볍게</Text></View><Switch value={haptic} onValueChange={setHaptic} trackColor={{true:'#71efba'}}/></View>
        <View style={s.row}><Text style={s.label}>클릭 소리</Text><Switch value={sound} onValueChange={setSound} trackColor={{true:'#71efba'}}/></View>
        <Text style={s.label}>기기 출력 보정 · {advance}ms 앞당김</Text>
        <View style={s.center}>{button('− 5ms',()=>setAdvance(Math.max(-100,advance-5)))}{button('진동 테스트',()=>Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy).catch(()=>setStatus('진동을 사용할 수 없습니다.')))}{button('+ 5ms',()=>setAdvance(Math.min(100,advance+5)))}</View>
        <Text style={s.note}>진동이 늦게 느껴지면 +로 조절하세요. 이 기기에만 적용됩니다.</Text>
      </View>
      <View style={s.card}>
        <Text style={s.section}>밴드와 연결</Text>
        <Text style={s.muted}>Wi-Fi가 달라도, 모바일 데이터에서도 방 코드로 참여해요.</Text>
        {!RELAY&&<><Text style={s.note}>배포 준비 중 · 온라인 중계 서버 주소가 아직 설정되지 않았습니다.</Text><TextInput accessibilityLabel="개발용 중계 서버 주소" placeholder="wss://배포한서버/sync" placeholderTextColor="#7b8b85" editable={!room&&!busy} value={address} onChangeText={setAddress} autoCapitalize="none" autoCorrect={false} style={s.input}/></>}
        {!room?<>
          <TextInput accessibilityLabel="멤버 이름" value={name} onChangeText={setName} editable={!busy} maxLength={20} style={s.input}/>
          <TextInput accessibilityLabel="방 코드" placeholder="6자리 방 코드" placeholderTextColor="#7b8b85" value={code} onChangeText={setCode} editable={!busy} autoCapitalize="characters" autoCorrect={false} maxLength={6} style={s.input}/>
          <View style={s.center}>{button('내 폰으로 방 만들기',()=>connect(true),false,busy||state.playing||!address)}{button('참여하기',()=>connect(false),true,busy||state.playing||!address||code.trim().length!==6)}</View>
        </>:<>
          <View style={s.center}>{button('코드 공유',()=>Share.share({message:`Pulse Band 방 코드: ${room.code}\n앱에서 코드를 입력해 참여하세요.`}).catch(()=>setStatus('공유를 열지 못했습니다.')))}{button(room.isHost?'방 종료':'방 나가기',leave,false,busy)}</View>
          {members.map(m=><View key={m.id} style={s.row}><Text style={s.label}>{m.name}{m.host?' · 방장':''}</Text><Text style={s.muted}>{!m.connected?'연결 끊김':m.ready?'준비 완료':'동기화 중'}</Text></View>)}
        </>}
        <Text style={s.note}>{status}</Text>
      </View>
      <Text style={s.footer}>화면을 켠 상태로 사용하세요. 방장 연결이 끊기면 재생이 멈춥니다.{ '\n'}실제 기기 간 진동 오차는 검증 전입니다.</Text>
    </ScrollView>
  </View>;
}
