const clampBpm = value => Math.max(30, Math.min(240, Math.round(Number(value) || 120)));
function clockSample(sent, received, serverTime) {
  return { rtt: received - sent, offset: serverTime - (sent + received) / 2 };
}
function bestClock(samples) {
  const best = [...samples].sort((a,b)=>a.rtt-b.rtt).slice(0,3);
  if (!best.length) throw Error('No clock samples');
  return { offset: best.map(x=>x.offset).sort((a,b)=>a-b)[Math.floor(best.length/2)], rtt: best[0].rtt };
}
function nextBeat(now, state, advance = 0) {
  const period = 60000 / state.bpm;
  const index = Math.max(0, Math.ceil((now + advance - state.startAt) / period));
  return { index, at: state.startAt + index * period - advance };
}
module.exports = { clampBpm, clockSample, bestClock, nextBeat };

