const {bestClock} = require('./core.cjs');

class SyncedClock {
  constructor(monotonic=()=>performance.now()) {
    this.local=monotonic;this.offset=Date.now()-this.local();this.target=this.offset;this.last=this.local();
  }
  set(offset,immediate=false) {this.target=offset;if(immediate){this.offset=offset;this.last=this.local();}}
  now() {
    const local=this.local(),elapsed=Math.max(0,local-this.last);this.last=local;
    // Slew at <=2ms/second so a new estimate cannot jump through an audible beat.
    const limit=elapsed*.002;
    this.offset+=Math.max(-limit,Math.min(limit,this.target-this.offset));
    return local+this.offset;
  }
}

class SyncClient {
  constructor({url,WebSocketImpl=globalThis.WebSocket,onSnapshot=()=>{},onStatus=()=>{},onClosed=()=>{}}) {
    this.url=url;this.WebSocketImpl=WebSocketImpl;this.onSnapshot=onSnapshot;this.onStatus=onStatus;this.onClosed=onClosed;
    this.clock=new SyncedClock();this.pending=new Map();this.id=0;this.session=null;this.ready=false;this.closed=false;this.retry=0;this.rtt=0;this.samples=[];this.lastContact=0;
  }
  isHealthy() {return this.ready&&performance.now()-this.lastContact<3500;}
  async request(type,data={}) {
    if(this.socket?.readyState!==1)throw Error('서버에 연결되어 있지 않습니다.');
    const id=++this.id;
    return new Promise((resolve,reject)=> {
      const timeout=setTimeout(()=>{this.pending.delete(id);reject(Error('서버 응답 시간이 초과됐습니다.'));},4000);
      this.pending.set(id,{resolve,reject,timeout});
      try{this.socket.send(JSON.stringify({type,id,...data}));}catch(e){clearTimeout(timeout);this.pending.delete(id);reject(e);}
    });
  }
  rejectPending() {for(const p of this.pending.values()){clearTimeout(p.timeout);p.reject(Error('연결이 끊겼습니다.'));}this.pending.clear();}
  async openTransport() {
    if(!/^wss:\/\//.test(this.url) && !/^ws:\/\/(localhost|127\.0\.0\.1)(:\d+)?\/sync$/.test(this.url))throw Error('배포된 중계 서버의 wss 주소가 필요합니다.');
    this.ready=false;this.onStatus({phase:'connecting'});
    await new Promise((resolve,reject)=> {
      const socket=new this.WebSocketImpl(this.url);this.socket=socket;
      let opened=false;
      const timeout=setTimeout(()=>{socket.close();reject(Error('서버 연결 시간이 초과됐습니다.'));},8000);
      socket.onopen=()=>{clearTimeout(timeout);opened=true;resolve();};
      socket.onerror=()=>{if(!opened){clearTimeout(timeout);reject(Error('중계 서버에 연결하지 못했습니다.'));}};
      socket.onmessage=event=> {
        if(this.socket!==socket||this.closed)return;
        let d;try{d=JSON.parse(event.data);}catch{return;}
        this.lastContact=performance.now();
        if(d.type==='reply') {
          const p=this.pending.get(d.id);if(!p)return;clearTimeout(p.timeout);this.pending.delete(d.id);d.error?p.reject(Error(d.error)):p.resolve(d);
        } else if(d.type==='snapshot')this.onSnapshot(d);
        else if(d.type==='roomClosed'){this.session=null;this.ready=false;this.onClosed();this.close();}
      };
      socket.onclose=event=> {
        clearTimeout(timeout);
        if(this.socket!==socket)return;
        this.ready=false;clearInterval(this.heartbeat);this.rejectPending();
        if(!opened)reject(Error('서버 연결이 종료됐습니다.'));
        if(event.code===4001){this.session=null;this.onClosed();this.close();return;}
        if(!this.closed&&!this.suspended&&this.session){this.onStatus({phase:'reconnecting'});this.scheduleReconnect();}
      };
    });
  }
  async sample() {
    const sent=performance.now();const d=await this.request('ping');const received=performance.now();
    const processing=d.serverSent-d.serverReceived;
    return {rtt:Math.max(0,received-sent-processing),offset:((d.serverReceived-sent)+(d.serverSent-received))/2};
  }
  async calibrate() {
    this.onStatus({phase:'syncing'});this.samples=[];
    for(let i=0;i<9;i++)this.samples.push(await this.sample());
    const best=bestClock(this.samples);this.clock.set(best.offset,true);this.rtt=best.rtt;
    await this.request('ready',{rtt:this.rtt});this.ready=true;this.retry=0;this.onStatus({phase:'ready',rtt:this.rtt});
    let checking=false,count=0;
    clearInterval(this.heartbeat);
    this.heartbeat=setInterval(async()=> {
      if(checking||this.closed)return;checking=true;
      try {
        this.samples.push(await this.sample());this.samples=this.samples.slice(-12);
        const best=bestClock(this.samples);this.clock.set(best.offset);this.rtt=best.rtt;
        if(++count%10===0){await this.request('ready',{rtt:this.rtt});this.onStatus({phase:'ready',rtt:this.rtt});}
      }catch{if(!this.closed)this.socket?.close();}finally{checking=false;}
    },1000);
  }
  async connect({create,code,name}) {
    this.closed=false;
    try {
      // A free hosting instance can take roughly a minute to wake up.
      // This affects entering a room, never the per-beat playback path.
      if(this.url.startsWith('wss://')) {
        this.onStatus({phase:'warming'});
        this.wakeController=new AbortController();
        const timeout=setTimeout(()=>this.wakeController?.abort(),75000);
        try {
          const healthUrl=this.url.replace(/^wss:/,'https:').replace(/\/sync$/,'/health');
          const response=await fetch(healthUrl,{signal:this.wakeController.signal});
          const data=await response.json();
          if(!response.ok||data.service!=='pulse-band-relay')throw Error('중계 서버가 준비되지 않았습니다.');
        }finally{clearTimeout(timeout);this.wakeController=null;}
      }
      if(this.closed||this.suspended)throw Error('연결이 취소되었습니다.');
      await this.openTransport();
      const d=await this.request(create?'create':'join',{code:code?.trim().toUpperCase(),name});
      this.session=d.session;this.onSnapshot(d);
      await this.calibrate();return this.session;
    }catch(e){this.close();throw e;}
  }
  scheduleReconnect() {
    clearTimeout(this.reconnectTimer);
    this.reconnectTimer=setTimeout(async()=> {
      if(this.closed||this.suspended||!this.session)return;
      try {
        await this.openTransport();
        let d;
        try{d=await this.request('resume',{code:this.session.code,token:this.session.token});}
        catch(e){if(this.socket?.readyState===1){this.session=null;this.onClosed();this.close();return;}throw e;}
        if(this.closed)return;
        this.session=d.session;this.onSnapshot(d);await this.calibrate();
      }catch{if(!this.closed&&!this.suspended&&this.session){const old=this.socket;this.socket=null;old?.close();this.scheduleReconnect();}}
    },Math.min(8000,500*2**this.retry++));
  }
  async update(state) {
    if(!this.isHealthy())throw Error('동기화가 끝나면 다시 시도하세요.');
    if(!this.session?.isHost)throw Error('방장 휴대폰만 제어할 수 있습니다.');
    return this.request('set',{bpm:state.bpm,beats:state.beats,playing:state.playing,revision:state.revision});
  }
  async leave() {try{await this.request('leave');}finally{this.close();}}
  suspend() {this.suspended=true;this.ready=false;clearTimeout(this.reconnectTimer);clearInterval(this.heartbeat);this.socket?.close();}
